package io.asv.odinlab;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.os.Bundle;
import android.provider.MediaStore;
import android.widget.*;
import androidx.core.content.FileProvider;
import java.io.*;
import java.lang.ref.WeakReference;
import java.nio.file.Files;
import java.util.*;
import java.util.concurrent.Executors;
import org.json.*;

/** Manual shutter and image picker, with app-private paired results. */
public class ScanActivity extends Activity {
 private static volatile boolean busy;
 private static volatile String message="Fotografía una carta completa. Para multitarjeta usa «Comparar detectores».";
 private static volatile File lastDir;
 private static WeakReference<ScanActivity> visible=new WeakReference<>(null);
 private File pending;private Uri cameraUri;private boolean pendingCrop,pendingMulti;
 private Spinner detectorView;private LinearLayout column;private TextView output;private ImageView preview;private CheckBox crop;private final List<Button> controls=new ArrayList<>();
 @Override public void onCreate(Bundle state){super.onCreate(state);
  column=new LinearLayout(this);column.setOrientation(LinearLayout.VERTICAL);column.setPadding(24,32,24,24);
  TextView title=new TextView(this);title.setText("Captura pareada · codex/dinov2-benchmark\nSOLO LABORATORIO · sin colección");title.setTextSize(20);column.addView(title);
  TextView help=new TextView(this);help.setText("Cornelius propone un recorte común; Milo y Diego buscan en el catálogo instalado. Top-5, no confianza calibrada. Revisa el borde amarillo y la carta real antes de valorar. No determina foil. Cámara manual del sistema, no vídeo continuo.");column.addView(help);
  crop=new CheckBox(this);crop.setText("La imagen YA es un recorte de una carta (omitir Cornelius)");column.addView(crop);
  button("Fotografiar y comparar",()->launch(true,false));button("Abrir foto y comparar",()->launch(false,false));button("Comparar detectores · cámara",()->launch(true,true));button("Comparar detectores · foto",()->launch(false,true));button("Detectores sobre última foto guardada",this::repeatDetectors);button("Elegir captura del laboratorio",this::chooseCapture);button("Comparar foto de las 16 cartas",this::demoDetectors);
  detectorView=new Spinner(this);detectorView.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,DetectorComparison.MODES));column.addView(detectorView);detectorView.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,android.view.View v,int pos,long id){refresh();}public void onNothingSelected(AdapterView<?> p){}});
  preview=new ImageView(this);preview.setAdjustViewBounds(true);preview.setMaxHeight(650);column.addView(preview);
  output=new TextView(this);output.setTextIsSelectable(true);column.addView(output);
  button("Valorar resultado (sin añadir cartas)",this::rate);button("Buscar referencia · nombre inglés / set",this::searchCatalog);
  ScrollView scroll=new ScrollView(this);scroll.addView(column);setContentView(scroll);
  if(state!=null){String path=state.getString("pending");if(path!=null)pending=new File(path);pendingCrop=state.getBoolean("crop");pendingMulti=state.getBoolean("multi");String uri=state.getString("uri");if(uri!=null)cameraUri=Uri.parse(uri);}
  if(lastDir==null){String path=getPreferences(0).getString("last",null);if(path!=null)lastDir=new File(path);}
 }
 private void button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setOnClickListener(v->action.run());controls.add(b);column.addView(b);}
 @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);if(pending!=null)b.putString("pending",pending.toString());if(cameraUri!=null)b.putString("uri",cameraUri.toString());b.putBoolean("crop",pendingCrop);b.putBoolean("multi",pendingMulti);}
 @Override protected void onStart(){super.onStart();visible=new WeakReference<>(this);refresh();}
 @Override protected void onStop(){if(visible.get()==this)visible.clear();super.onStop();}
 @Override public void onBackPressed(){if(busy)Toast.makeText(this,"Espera a que se guarden los resultados",Toast.LENGTH_SHORT).show();else super.onBackPressed();}
 private static void notifyUi(){ScanActivity a=visible.get();if(a!=null)a.runOnUiThread(a::refresh);}
 private void launch(boolean camera,boolean multi){if(busy)return;
  if(camera&&checkSelfPermission(android.Manifest.permission.CAMERA)!=android.content.pm.PackageManager.PERMISSION_GRANTED){pendingMulti=multi;requestPermissions(new String[]{android.Manifest.permission.CAMERA},41);return;}
  pendingCrop=crop.isChecked();pendingMulti=multi;
  try{pending=new File(getFilesDir(),"captures/"+System.currentTimeMillis()+"-"+UUID.randomUUID().toString().substring(0,8));if(!pending.mkdirs())throw new IOException("Carpeta captura");
   if(camera){File photo=new File(pending,"source.jpg");cameraUri=FileProvider.getUriForFile(this,"io.asv.odinlab.capture",photo);Intent i=new Intent(MediaStore.ACTION_IMAGE_CAPTURE).putExtra(MediaStore.EXTRA_OUTPUT,cameraUri).addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newRawUri("Captura laboratorio",cameraUri));startActivityForResult(i,10);}
   else startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE),11);
  }catch(Exception e){message=e.toString();refresh();}
 }
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=10&&request!=11)return;
  if(cameraUri!=null){revokeUriPermission(cameraUri,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);cameraUri=null;}
  if(result!=RESULT_OK||pending==null)return;
  File dir=pending;boolean isCrop=pendingCrop,multi=pendingMulti;Uri source=request==10?Uri.fromFile(new File(dir,"source.jpg")):(data==null?null:data.getData());if(source==null)return;
  busy=true;message="Preparando captura y modelos… (la carga inicial no cuenta como inferencia)";lastDir=dir;getPreferences(0).edit().putString("last",dir.toString()).apply();refresh();Context app=getApplicationContext();
  var worker=Executors.newSingleThreadExecutor();worker.execute(()->{Bitmap bitmap=null;try{
   File original=new File(dir,request==10?"source.jpg":"source.image");if(request!=10)try(InputStream in=app.getContentResolver().openInputStream(source);OutputStream out=new FileOutputStream(original)){if(in==null)throw new IOException("Foto inaccesible");byte[] bytes=new byte[65536];int n;long total=0;while((n=in.read(bytes))!=-1){total+=n;if(total>80_000_000)throw new IOException("Foto supera 80 MB");out.write(bytes,0,n);}}
   // ImageDecoder applies EXIF orientation. Bound decode memory, retain original bytes.
   bitmap=ImageDecoder.decodeBitmap(ImageDecoder.createSource(original),(d,info,s)->{d.setAllocator(ImageDecoder.ALLOCATOR_SOFTWARE);int w=info.getSize().getWidth(),h=info.getSize().getHeight();double scale=Math.min(1.,2048./Math.max(w,h));d.setTargetSize(Math.max(1,(int)(w*scale)),Math.max(1,(int)(h*scale)));});
   CaptureEngine.png(new File(dir,"input.png"),bitmap);
   if(multi){DetectorComparison.run(app,dir,bitmap);message="Detección Android terminada. Elige overlay: Cornelius / tmikonen original / variante sin marco. Propuestas ≠ aciertos.";}
   else{CaptureEngine.run(app,dir,bitmap,isCrop);message="Comparación terminada. Revisa el recorte y valora ambos modelos.";}
  }catch(Exception e){message="No se pudo completar: "+e;try{CaptureEngine.save(dir,"error.json",new JSONObject().put("error",e.toString()));}catch(Exception ignored){}android.util.Log.e("DiegoLab","capture",e);}
  finally{if(bitmap!=null)bitmap.recycle();busy=false;notifyUi();worker.shutdown();}});
 }
 private void refresh(){if(isDestroyed()||output==null)return;for(Button b:controls)b.setEnabled(!busy);crop.setEnabled(!busy);StringBuilder text=new StringBuilder(message).append('\n');
  if(lastDir!=null){text.append("Prueba: ").append(lastDir.getName()).append('\n');File image=new File(lastDir,new File(lastDir,"detectors.json").exists()?detectorView.getSelectedItem().toString()+".png":"overlay.png");if(!image.exists())image=new File(lastDir,"input.png");if(image.exists()){BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=2;preview.setImageBitmap(BitmapFactory.decodeFile(image.toString(),options));}else preview.setImageDrawable(null);
   if(!busy&&new File(lastDir,"detectors.json").exists())try{JSONObject modes=new JSONObject(new String(Files.readAllBytes(new File(lastDir,"detectors.json").toPath()),java.nio.charset.StandardCharsets.UTF_8)).getJSONObject("modes");text.append("\nTMikonen port Java/JTS · cálculos locales Sony\nCornelius propone una sola carta, no es multitarjeta.\n");for(String mode:DetectorComparison.MODES){JSONObject m=modes.getJSONObject(mode);text.append(mode).append(": ");if(m.has("error"))text.append(m.getString("error"));else text.append(m.getInt("proposals")).append(String.format(Locale.ROOT," propuestas · %.1f ms",m.getDouble("median_ms"))).append(" · geometrías rechazadas ").append(m.getInt("geometry_rejected"));text.append('\n');}text.append("Tiempos: detección+preprocesado+NMS, 3 repeticiones tras calentamiento; sin cámara/carga/overlay. Son propuestas, no identificación de cartas.\n");}catch(Exception e){text.append(e);}
   if(!busy)try{JSONObject r=new JSONObject(new String(Files.readAllBytes(new File(lastDir,"result.json").toPath()),java.nio.charset.StandardCharsets.UTF_8));text.append(String.format(Locale.ROOT,"Cornelius %.1f ms · recorte %.1f ms\n",r.getDouble("detector_ms"),r.getDouble("warp_ms")));JSONArray rows=r.getJSONArray("rows");for(String mode:new String[]{"milo","diego"}){double[] times=new double[3];JSONObject first=null;int count=0;for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(row.getString("mode").equals(mode)){times[count++]=row.getDouble("total_ms");if(first==null)first=row;}}Arrays.sort(times);text.append('\n').append(mode.toUpperCase(Locale.ROOT)).append(String.format(Locale.ROOT," · mediana %.1f ms (3 repeticiones)\n",times[1]));JSONArray top=first.getJSONArray("top");for(int k=0;k<top.length();k++){JSONObject p=top.getJSONObject(k);text.append(k+1).append(". ").append(p.getString("label")).append(String.format(Locale.ROOT," [%.3f]\n",p.getDouble("cosine")));}}
    text.append("\nTiempo = preprocesado + inferencia vertical única° + búsqueda; sin cámara/carga/guardado. La similitud no es probabilidad de acierto.");if(new File(lastDir,"rating.json").exists())text.append("\nValoración guardada.");
   }catch(Exception ignored){}
  }output.setText(text.toString());
 }
 private void repeatDetectors(){if(busy||lastDir==null||!new File(lastDir,"input.png").exists()){Toast.makeText(this,"Primero toma o abre una foto",Toast.LENGTH_SHORT).show();return;}File source=new File(lastDir,"input.png");Context app=getApplicationContext();busy=true;message="Comparando detectores en Sony…";refresh();var worker=Executors.newSingleThreadExecutor();worker.execute(()->{Bitmap bitmap=null;try{File dir=new File(app.getFilesDir(),"captures/"+System.currentTimeMillis()+"-detectors");if(!dir.mkdirs())throw new IOException("mkdir");Files.copy(source.toPath(),new File(dir,"input.png").toPath());bitmap=BitmapFactory.decodeFile(source.toString());lastDir=dir;getPreferences(0).edit().putString("last",dir.toString()).apply();DetectorComparison.run(app,dir,bitmap);message="Comparación guardada aparte; foto anterior intacta.";}catch(Exception e){message=e.toString();}finally{if(bitmap!=null)bitmap.recycle();busy=false;notifyUi();worker.shutdown();}});}
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] grants){super.onRequestPermissionsResult(code,permissions,grants);if(code==41&&grants.length>0&&grants[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)launch(true,pendingMulti);}
 private void chooseCapture(){if(busy)return;File[] dirs=new File(getFilesDir(),"captures").listFiles(f->f.isDirectory()&&new File(f,"input.png").exists());if(dirs==null||dirs.length==0)return;Arrays.sort(dirs,(a,b)->b.getName().compareTo(a.getName()));String[] names=new String[dirs.length];for(int i=0;i<dirs.length;i++)names[i]=dirs[i].getName();new AlertDialog.Builder(this).setTitle("Capturas privadas (más reciente primero)").setItems(names,(d,i)->{lastDir=dirs[i];getPreferences(0).edit().putString("last",lastDir.toString()).apply();message="Captura seleccionada; puedes repetir detectores sin alterar el resultado anterior.";refresh();}).show();}
 private void demoDetectors(){if(busy)return;busy=true;message="Comparando la foto de16cartas en Sony…";refresh();Context app=getApplicationContext();var executor=Executors.newSingleThreadExecutor();executor.execute(()->{Bitmap b=null;try{File dir=new File(app.getFilesDir(),"captures/"+System.currentTimeMillis()+"-demo16");if(!dir.mkdirs())throw new IOException("mkdir");try(InputStream in=app.getAssets().open("multi16.png")){b=BitmapFactory.decodeStream(in);}CaptureEngine.png(new File(dir,"input.png"),b);lastDir=dir;getPreferences(0).edit().putString("last",dir.toString()).apply();DetectorComparison.run(app,dir,b);message="Foto16 usada para ajustar reject-frame: NO es validación independiente.";}catch(Exception e){message=e.toString();}finally{if(b!=null)b.recycle();busy=false;notifyUi();executor.shutdown();}});}
 private void rateDetectors(){try{File dir=lastDir;String mode=detectorView.getSelectedItem().toString();JSONObject data=new JSONObject(new String(Files.readAllBytes(new File(dir,"detectors.json").toPath()),java.nio.charset.StandardCharsets.UTF_8)).getJSONObject("modes").getJSONObject(mode);int proposals=data.getInt("proposals");LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);EditText truth=new EditText(this),correct=new EditText(this);truth.setHint("Número real de cartas en la foto");correct.setHint("Propuestas correctas (4 bordes, sin duplicados)");truth.setInputType(2);correct.setInputType(2);form.addView(truth);form.addView(correct);new AlertDialog.Builder(this).setTitle("Valorar "+mode).setMessage(proposals+" propuestas. Cuenta como correcta solo una por carta, con los cuatro bordes bien delimitados.").setView(form).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(d,w)->{try{int n=Integer.parseInt(truth.getText().toString()),tp=Integer.parseInt(correct.getText().toString());if(n<1||tp<0||tp>n||tp>proposals)throw new IllegalArgumentException("Recuentos incompatibles");CaptureEngine.save(dir,"rating-"+mode+".json",new JSONObject().put("mode",mode).put("manual",true).put("truth_count",n).put("proposals",proposals).put("correct",tp).put("missed",n-tp).put("extra_or_bad_crop",proposals-tp));Toast.makeText(this,"Valoración guardada: "+tp+"/"+n+" cartas",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,e.toString(),Toast.LENGTH_LONG).show();}}).show();}catch(Exception e){Toast.makeText(this,"Este modo no tiene un resultado válido",Toast.LENGTH_LONG).show();}}
 private void searchCatalog(){EditText query=new EditText(this);query.setHint("Nombre inglés o SET #número (ej.: Ghalta)");new AlertDialog.Builder(this).setTitle("Cobertura del índice instalado").setMessage("Busca nombres ingleses. No encontrar un nombre español no demuestra ausencia. La búsqueda no descarga ni añade cartas.").setView(query).setNegativeButton("Cancelar",null).setPositiveButton("Buscar",(d,w)->{String term=query.getText().toString().trim().toLowerCase(Locale.ROOT);if(term.length()<3)return;busy=true;message="Buscando referencias…";refresh();Context app=getApplicationContext();var executor=Executors.newSingleThreadExecutor();executor.execute(()->{String result;try{JSONArray labels=CaptureEngine.array(app,"scan-labels.json");StringBuilder hits=new StringBuilder();int count=0;for(int i=0;i<labels.length();i++){String label=labels.getString(i);if(label.toLowerCase(Locale.ROOT).contains(term)){count++;if(count<=40)hits.append(label).append('\n');}}result=count+" referencias para «"+term+"» (máximo40 mostradas).\n"+hits+"\nEl índice es un snapshot. La versión se registra en cada resultado. Existir una referencia no garantiza reconocerla.";}catch(Exception e){result=e.toString();}final String shown=result;busy=false;runOnUiThread(()->{refresh();if(!isFinishing()&&!isDestroyed())new AlertDialog.Builder(this).setTitle("Cobertura").setMessage(shown).setPositiveButton("Cerrar",null).show();});executor.shutdown();});}).show();}
 private void rate(){if(!busy&&lastDir!=null&&new File(lastDir,"detectors.json").exists()){rateDetectors();return;}if(busy||lastDir==null||!new File(lastDir,"result.json").exists()){Toast.makeText(this,"Primero compara una carta",Toast.LENGTH_SHORT).show();return;}
  File dir=lastDir;LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);EditText truth=new EditText(this);truth.setHint("Carta real / edición / número / idioma");form.addView(truth);CheckBox quad=new CheckBox(this);quad.setText("Recorte correcto (4 bordes de la carta)");form.addView(quad);String[] choices={"Sin evaluar","Incorrecto","Nombre correcto (edición no comprobada)","Nombre + edición + número + idioma correctos"};Spinner milo=new Spinner(this),diego=new Spinner(this);for(Spinner s:new Spinner[]{milo,diego}){TextView label=new TextView(this);label.setText(s==milo?"Milo":"Diego");form.addView(label);s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,choices));form.addView(s);}
  new AlertDialog.Builder(this).setTitle("Valoración manual del top-1").setView(form).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(d,w)->{try{CaptureEngine.save(dir,"rating.json",new JSONObject().put("truth",truth.getText().toString()).put("crop_correct",quad.isChecked()).put("milo",milo.getSelectedItemPosition()).put("diego",diego.getSelectedItemPosition()).put("scale",new JSONArray(Arrays.asList(choices))));refresh();}catch(Exception e){Toast.makeText(this,e.toString(),Toast.LENGTH_LONG).show();}}).show();
 }
}
